fun h =>
  -- decomposition of the proposition:
    let htr       := h.left     -- (t → r)
    let h2        := h.right
    let hfr       := h2.left    -- (f → r)
    let h3        := h2.right
    let hrm       := h3.left    -- (r → m)
    let h4        := h3.right
    let hnmnf     := h4.left    -- (¬m ∨ ¬f)
    let ht        := h4.right   -- t
    let hr        := htr ht     -- r implied by t
    let hm        := hrm hr
